#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ks(n);
    vector<vector<pair<int,int>>> rawCells(n);
    int totalCells = 0;
    for(int i = 0; i < n; i++){
        cin >> ks[i];
        rawCells[i].resize(ks[i]);
        for(int j = 0; j < ks[i]; j++){
            cin >> rawCells[i][j].first >> rawCells[i][j].second;
        }
        totalCells += ks[i];
    }

    // Transform: first flip (negate x if f=1), then rotate r times 90° CCW
    // CCW rotation: (x,y) -> (-y, x)
    auto transform = [](const vector<pair<int,int>>& cells, int r, int f, int& w, int& h) -> vector<pair<int,int>> {
        vector<pair<int,int>> res;
        for(auto [x,y] : cells){
            int tx = x, ty = y;
            if(f) tx = -tx;
            for(int i = 0; i < r; i++){
                int nx = -ty, ny = tx;
                tx = nx; ty = ny;
            }
            res.push_back({tx, ty});
        }
        int minx = INT_MAX, miny = INT_MAX;
        for(auto [x,y] : res){ minx = min(minx,x); miny = min(miny,y); }
        for(auto& [x,y] : res){ x -= minx; y -= miny; }
        int mx = 0, my = 0;
        for(auto [x,y] : res){ mx = max(mx,x); my = max(my,y); }
        w = mx+1; h = my+1;
        return res;
    };

    // For each piece, generate all distinct orientations
    struct Orient { vector<pair<int,int>> cells; int w,h,r,f; };
    vector<vector<Orient>> allOrients(n);
    for(int i = 0; i < n; i++){
        set<vector<pair<int,int>>> seen;
        for(int f = 0; f < 2; f++){
            for(int r = 0; r < 4; r++){
                int w,h;
                auto c = transform(rawCells[i], r, f, w, h);
                sort(c.begin(), c.end());
                if(seen.insert(c).second){
                    allOrients[i].push_back({c, w, h, r, f});
                }
            }
        }
    }

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){ return ks[a] > ks[b]; });

    int bestArea = INT_MAX;
    vector<int> bestX(n), bestY(n), bestR(n), bestF(n);
    int bestW=0, bestH=0;

    int maxPW = 0;
    for(int i=0;i<n;i++) for(auto&o:allOrients[i]) maxPW=max(maxPW,o.w);

    for(int W = maxPW; W <= totalCells && W <= 500; W++){
        vector<int> sky(W, 0);
        set<pair<int,int>> occ;
        vector<int> px(n),py(n),pr(n),pf(n);
        bool ok = true; int curH = 0;
        for(int idx=0;idx<n;idx++){
            int i=order[idx]; int bs=INT_MAX,bx=-1,by=-1,boi=-1;
            for(int oi=0;oi<(int)allOrients[i].size();oi++){
                auto&ori=allOrients[i][oi];
                if(ori.w>W) continue;
                for(int x=0;x<=W-ori.w;x++){
                    int my=0;
                    for(auto[cx,cy]:ori.cells) my=max(my,sky[x+cx]-cy);
                    if(my<0)my=0;
                    bool good=true;
                    for(auto[cx,cy]:ori.cells) if(occ.count({x+cx,my+cy})){good=false;break;}
                    if(!good) continue;
                    int mh=0; for(auto[cx,cy]:ori.cells) mh=max(mh,my+cy+1);
                    int sc=max(curH,mh)*10000+mh*100+x;
                    if(sc<bs){bs=sc;bx=x;by=my;boi=oi;}
                }
            }
            if(boi<0){ok=false;break;}
            auto&ori=allOrients[i][boi];
            px[i]=bx;py[i]=by;pr[i]=ori.r;pf[i]=ori.f;
            for(auto[cx,cy]:ori.cells){occ.insert({bx+cx,by+cy});sky[bx+cx]=max(sky[bx+cx],by+cy+1);curH=max(curH,by+cy+1);}
        }
        if(!ok) continue;
        int area=W*curH;
        if(area<bestArea){bestArea=area;bestW=W;bestH=curH;bestX=px;bestY=py;bestR=pr;bestF=pf;}
    }

    cout << bestW << " " << bestH << "\n";
    for(int i=0;i<n;i++) cout << bestX[i] << " " << bestY[i] << " " << bestR[i] << " " << bestF[i] << "\n";
}
